import copy
import difflib
import json
def strip(nb):
    clean=copy.deepcopy(nb)
    for c in clean["cells"]:
        if c["cell_type"]=="code":
            c["outputs"]=[]
            c["execution_count"]=None
    return clean
def changed_lines(a,b):
    return sum(l[:1] in ["+","-"] and not l.startswith(("+++","---")) for l in difflib.unified_diff(a.splitlines(),b.splitlines()))
