def make_readme(info):
    lines=["# "+info["title"],"","## Вопрос",info["question"],"","## Данные",info["data"],"","## Главное"]
    lines += ["- "+s for s in info["findings"]]
    lines += ["","## Как запустить"]+["    "+s for s in info["run"]]
    return "\n".join(lines)
